    """ Calculate the arithmetic mean of a list of numbers
    >>> mean([1, 2, 3])
    2.0
    """
    if len(numbers) < 1:
        raise ValueError("Cannot calculate mean, need at least one number")

    return round(sum(numbers) / len(numbers), 1)


def mode(numbers: List[float]) -> float:
    """ Returns the most frequent value in a list of numbers (most common)
    >>> mode([1, 2, 2, 3])
    2.0
    """
    if len(numbers) < 1:
        raise ValueError("Cannot calculate mode, need at least one number")

    mode_value = max(numbers, key=numbers.count)
    return round(mode_value, 1)


