def median_absolute_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Median Absolute Deviation
    around the median of this dataset.
    Median Absolute Deviation is the median absolute difference between each
    element and a centerpoint (median in this case):
    MADS = median(| x - x_median |) in [x]
    >>> median_absolute_deviation([1.0, 2.0, 3.0, 4.0])
    1.0
    """
    sort = numbers.copy()
    sort.sort()
    median = sort[len(sort)//2]
    return median_absolute_deviation_aux(sort, median)

def median_absolute_deviation_aux(nums, target):
    if len(nums) == 1:
        return abs(nums[0] - target)

    left = median_absolute_deviation_aux(nums[:len(nums)//2], target)
    right = median_absolute_deviation_aux(nums[len(nums)//2:], target)
    return min(left, right)

