    """ Input to this function is a string of single group of nested parentheses with optional whitespace.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_parens("(()()) ((())) () ((())()())")
    3
    """

    cnt = 0
    for i in paren_string:
        if i == "(":
            cnt += 1
        elif i == ")":
            cnt -= 1
        if cnt < 0:
            return cnt
    return cnt


