def filter_by_substrings(strings: List[str], substrings: List[str]) -> List[str]:
    """ Filter an input list of strings only for ones that contain all given substrings
    Note that input list and its elements are unmodified.
    >>> filter_by_substrings(['abc', 'bacd', 'cde', 'array'], ['a', 'b'])
    ['abc', 'bacd', 'array']
    >>> filter_by_substrings(['abc', 'bacd', 'cde', 'array'], ['a', 'z'])
    []
    """
    res = []
    for string in strings:
        has_all = True
        for substring in substrings:
            if substring not in string:
                has_all = False
        if has_all:
            res.append(string)
    return res


