def count_nested_parentheses(paren_string: str) -> int:
    """Input to this function is a string representing a single group of nested parentheses.
    Return the maximum level of nesting of parentheses.

    >>> count_nested_parentheses('(()())')
    2
    """
    max_level = 0
    cur_level = 0
    for c in paren_string:
        if c == '(':
            cur_level += 1
            if max_level < cur_level:
                max_level = cur_level
        elif c == ')':
            cur_level -= 1
    return max_level


