def get_prime_factors(n: int) -> List[int]:
    """ Get a list with the prime factors.
    >>> get_prime_factors(15)
    [3, 5]
    """
    factors = []
    for i in range(2, n+1):
        while n % i == 0:
            factors.append(i)
            n //= i
    return factors


def check_prime(n: int) -> bool:
    """ Return True if the given number is a prime number.
    >>> check_prime(7)
    True
    """
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, int(sqrt(n))+1, 6):
        if n % i == 0 or n % (i+2) == 0:
            return False
    return

