def is_perfect_binary_tree(root):
    def is_complete(node, layer, expected_layer):
        if node is None:
            return True
        if node.left and node.right:
            return (layer == expected_layer and is_complete(node.left, layer + 1, expected_layer)) and \
                    (is_complete(node.right, layer + 1, expected_layer))
        elif node.left or node.right:
            return False
        else:
            return layer == expected_layer
    return is_complete(root, 0, 0) and all(n is None for node in root.children for n in node.children)


